configuration:
yarn.resourcemanager.hostname {{__master_yarn}}
yarn.resourcemanager.bind-host 0.0.0.0
yarn.resourcemanager.webapp.address 0.0.0.0:8088
yarn.nodemanager.aux-services mapreduce_shuffle
yarn.nodemanager.hostname {{__ip}}
yarn.nodemanager.env-whitelist JAVA_HOME,HADOOP_COMMON_HOME,HADOOP_HDFS_HOME,HADOOP_CONF_DIR,CLASSPATH_PREPEND_DISTCACHE,HADOOP_YARN_HOME,HADOOP_MAPRED_HOME,HADOOP_HOME,PATH,LANG,TZ
yarn.nodemanager.resource.memory-mb {{nm_mem}}
yarn.nodemanager.resource.cpu-vcores {{nm_vcores}}
yarn.scheduler.minimum-allocation-mb 512
yarn.scheduler.maximum-allocation-mb {{nm_mem}}
yarn.log-aggregation-enable true
yarn.application.classpath /opt/hadoop/etc/hadoop,/opt/hadoop/share/hadoop/common/*,/opt/hadoop/share/hadoop/common/lib/*,/opt/hadoop/share/hadoop/hdfs/*,/opt/hadoop/share/hadoop/hdfs/lib/*,/opt/hadoop/share/hadoop/yarn/*,/opt/hadoop/share/hadoop/yarn/lib/*,/opt/hadoop/share/hadoop/mapreduce/*,/opt/hadoop/share/hadoop/mapreduce/lib/*
{{__ha_yarn_props}}
